'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Compute fitted KMeans cluster results for double-precision floating-point strided array data using Lloyd's algorithm.
* @param {PositiveInteger} M - number of samples
* @param {PositiveInteger} N - number of features
* @param {PositiveInteger} k - number of clusters
* @param {NonNegativeInteger} replicates - number of times to repeat clustering with different centroids.
* @param {String} metric - distance metric
* @param {NonNegativeInteger} maxIter - maximum number of iterations.
* @param {number} tol - relative tolerance before declaring convergence.
* @param {Float64Array} X - input strided matrix
* @param {integer} strideX1 - stride of the first dimension.
* @param {integer} strideX2 - stride of the second dimension.
* @param {Float64Array} init - strided array containing initial centroid locations.
* @param {integer} strideInit1 - stride of first dimension.
* @param {integer} strideInit2 - stride of second dimension.
* @param {integer} strideInit3 - stride of the third dimension.
* @param {Float64Array} bestCentroids - strided array buffer for final centroid locations.
* @param {integer} strideC1 - stride of first dimensions of C.
* @param {integer} strideC2 - stride of second dimensions of C.
* @param {Float64Array} statistics - strided array buffer for cluster stats.
* @param {integer} strideS1 - stride of first dimensions of S.
* @param {integer} strideS2 - stride of second dimensions of S.
* @param {Int32Array} bestLabels - strided array buffer for sample labels.
* @param {integer} strideL - stride of first dimensions of labels.
* @param {Object} out - output results object.
*/
function dkmeansld( M, N, k, replicates, metric, maxIter, tol, X, strideX1, strideX2, init, strideInit1, strideInit2, strideInit3, bestCentroids, strideC1, strideC2, statistics, strideS1, strideS2, bestLabels, strideL, out ) { // eslint-disable-line max-len, max-params
	addon( M, N, k, replicates, metric, maxIter, tol, X, strideX1, strideX2, init, strideInit1, strideInit2, strideInit3, bestCentroids, strideC1, strideC2, statistics, strideS1, strideS2, bestLabels, strideL, out ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = dkmeansld;
